style:
.home { max-inline-size: 72rem; margin-inline: auto; padding: var(--feitio-space-6) var(--feitio-space-4) var(--feitio-space-7); }
.home > section + section { margin-block-start: var(--feitio-space-7); }
.home h2 { margin: 0; font: var(--feitio-font-weight-bold) var(--feitio-font-size-h1)/1.1 var(--feitio-font-ui); }
.home .sub { margin: var(--feitio-space-2) 0 0; max-inline-size: 60ch; font: var(--feitio-font-size-body)/var(--feitio-line-height-text) var(--feitio-font-text); color: var(--feitio-color-text-soft); }
.home section > .sub + :not(.sub) { margin-block-start: var(--feitio-space-5); }
.hero { display: grid; gap: var(--feitio-space-6); align-items: center; }
@media (min-width: 60rem) { .hero { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--feitio-space-7); padding-block: var(--feitio-space-5); } }
.hero .lockup { display: flex; align-items: center; gap: var(--feitio-space-3); }
.hero-mark.mark-big { inline-size: clamp(4rem, 9vw, 6rem); block-size: clamp(4rem, 9vw, 6rem); flex: none; overflow: visible; }
.mark-big path { fill: none; stroke: var(--feitio-color-text); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }
.mark-big .paper { fill: var(--feitio-color-surface-top); stroke: none; }
.mark-big .shadow { fill: var(--feitio-color-shadow); stroke: none; }
.mark-big .hot { stroke: var(--feitio-color-accent); }
.hero h1 { margin: 0; font: var(--feitio-font-weight-heavy) clamp(3.5rem, 11vw, 6.5rem)/0.95 var(--feitio-font-ui); letter-spacing: -0.01em; }
.hero .tagline { margin: var(--feitio-space-3) 0 0; font: var(--feitio-font-weight-medium) clamp(1.35rem, 3vw, 1.8rem)/1.25 var(--feitio-font-ui); max-inline-size: 26ch; }
.hero .lede { margin: var(--feitio-space-3) 0 0; max-inline-size: 46ch; font: var(--feitio-font-size-body)/var(--feitio-line-height-text) var(--feitio-font-text); color: var(--feitio-color-text-soft); }
.hero .actions { margin-block-start: var(--feitio-space-5); }
.mosaic { position: relative; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: var(--feitio-space-4); max-inline-size: 34rem; inline-size: 100%; justify-self: center; font-family: var(--feitio-font-ui); }
.mosaic .sheet { padding: var(--feitio-space-4); background: var(--feitio-color-surface-top); border: var(--feitio-border-width) solid var(--feitio-color-text); border-radius: var(--feitio-radius); box-shadow: var(--feitio-shadow-lift); }
.mosaic .sheet h3 { margin: 0; font: var(--feitio-font-weight-bold) var(--feitio-font-size-h3)/1.2 var(--feitio-font-ui); }
.mosaic .sheet p { margin: 0; font-size: var(--feitio-font-size-small); color: var(--feitio-color-text-soft); }
.mosaic .s1 { grid-column: 1 / 5; rotate: -1.2deg; }
.mosaic .s2 { grid-column: 4 / 7; grid-row: 1; align-self: end; margin-block-end: calc(-1 * var(--feitio-space-6)); rotate: 1.4deg; z-index: 1; }
.mosaic .s3 { grid-column: 1 / 4; rotate: 0.8deg; }
.mosaic .s4 { grid-column: 3 / 7; rotate: -0.6deg; margin-inline-start: var(--feitio-space-5); }
@media (max-width: 40rem) {
    .mosaic { grid-template-columns: minmax(0, 1fr); max-inline-size: 22rem; gap: var(--feitio-space-3); }
    .mosaic .s1, .mosaic .s2, .mosaic .s3, .mosaic .s4 { grid-column: 1; grid-row: auto; margin: 0; }
    .mosaic .s3 { display: none; }
  }
.values { display: grid; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); gap: var(--feitio-space-5); margin: 0; padding: 0; list-style: none; }
.values h3 { margin: var(--feitio-space-3) 0 0; font: var(--feitio-font-weight-bold) var(--feitio-font-size-h3) var(--feitio-font-ui); }
.values p { margin: var(--feitio-space-2) 0 0; font: var(--feitio-font-size-small)/var(--feitio-line-height-text) var(--feitio-font-ui); color: var(--feitio-color-text-soft); }
.val-art { inline-size: 2.75rem; block-size: 2.75rem; fill: none; stroke: var(--feitio-color-text); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; rotate: -3deg; }
.val-art .hot { stroke: var(--feitio-color-accent); }
.board { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); grid-auto-rows: minmax(10rem, auto); gap: var(--feitio-space-4); padding: var(--feitio-space-5); background: var(--feitio-color-surface-raised); border-radius: var(--feitio-radius); font-family: var(--feitio-font-ui); }
.piece { display: grid; grid-template-rows: minmax(0, 1fr) auto; background: var(--feitio-color-surface-top); border: var(--feitio-border-width) solid var(--feitio-color-text); border-radius: var(--feitio-radius); box-shadow: var(--feitio-shadow-lift); overflow: hidden; }
.piece > .feitio-stack { align-content: center; justify-items: center; padding: var(--feitio-space-5) var(--feitio-space-4); }
.piece .cap { padding: var(--feitio-space-2) var(--feitio-space-4); font: var(--feitio-font-weight-bold) 0.75rem/1.4 var(--feitio-font-ui); letter-spacing: 0.02em; color: var(--feitio-color-text-soft); border-block-start: var(--feitio-border-width) solid var(--feitio-color-line); }
.piece p { margin: 0; font-size: var(--feitio-font-size-small); color: var(--feitio-color-text-soft); }
.piece .pt { font: var(--feitio-font-weight-bold) var(--feitio-font-size-h3)/1.2 var(--feitio-font-ui); }
.piece .feitio-notice { margin: 0; inline-size: 100%; }
.b-form > .feitio-stack { justify-items: stretch; align-content: start; }
.b-form .actions { justify-self: start; }
.b-dialog > .feitio-stack { justify-items: start; }
.mini-empty { display: grid; justify-items: center; gap: var(--feitio-space-2); text-align: center; font-size: var(--feitio-font-size-small); }
.mini-empty svg { inline-size: 6rem; block-size: auto; }
.b-form { grid-column: span 5; grid-row: span 2; }
.b-dialog { grid-column: span 4; }
.b-empty { grid-column: span 3; grid-row: span 2; }
.b-notice { grid-column: span 4; }
.b-tag { grid-column: span 4; }
.b-seg { grid-column: span 3; }
.b-kbd { grid-column: span 2; }
.b-swatch { grid-column: span 3; }
@media (max-width: 60rem) { .board { grid-template-columns: repeat(2, minmax(0, 1fr)); padding: var(--feitio-space-4); } .board .piece { grid-column: span 1; grid-row: auto; } .b-form, .b-dialog, .b-notice, .b-tag { grid-column: span 2 !important; } }
@media (max-width: 34rem) { .board { grid-template-columns: minmax(0, 1fr); } .board .piece { grid-column: auto !important; } .b-kbd, .b-swatch { display: none; } }
.showcase { display: grid; grid-template-columns: repeat(auto-fill, minmax(17rem, 1fr)); gap: var(--feitio-space-4); margin: 0; padding: 0; list-style: none; }
.show-card { display: grid; grid-template-rows: 1fr auto; border: var(--feitio-border-width) solid var(--feitio-color-text); border-radius: var(--feitio-radius); background: var(--feitio-color-surface-top); overflow: hidden; }
.show-live { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: var(--feitio-space-3); min-block-size: 9rem; padding: var(--feitio-space-5) var(--feitio-space-4); background: var(--feitio-color-surface-raised); border-block-end: var(--feitio-border-width) solid var(--feitio-color-line); }
.show-about { display: grid; gap: var(--feitio-space-1); padding: var(--feitio-space-4); font: var(--feitio-font-size-small)/1.4 var(--feitio-font-ui); color: var(--feitio-color-text-soft); }
.show-about strong { font: var(--feitio-font-weight-bold) var(--feitio-font-size-h3) var(--feitio-font-ui); color: var(--feitio-color-text); }
.show-about .feitio-link { margin-block-start: var(--feitio-space-2); display: inline-flex; align-items: center; gap: var(--feitio-space-1); inline-size: fit-content; font-weight: var(--feitio-font-weight-bold); }
.show-live .feitio-details { inline-size: 100%; }
.home dialog.feitio-dialog { margin: auto; }
.show-more { margin-block-start: var(--feitio-space-5); }
.try { display: grid; gap: var(--feitio-space-5); align-items: start; }
@media (min-width: 56rem) { .try { grid-template-columns: 17rem minmax(0, 1fr); } }
.try-controls { display: grid; gap: var(--feitio-space-4); }
.try-control { display: grid; gap: var(--feitio-space-2); }
.try-label { font: var(--feitio-font-weight-bold) var(--feitio-font-size-small) var(--feitio-font-ui); }
.try-controls .feitio-segmented { inline-size: fit-content; max-inline-size: 100%; flex-wrap: wrap; }
.try-hint { margin-block-start: calc(-1 * var(--feitio-space-1)); font: var(--feitio-font-size-small)/1.45 var(--feitio-font-ui); color: var(--feitio-color-text-soft); }
.try-calm { margin: 0; font: var(--feitio-font-size-small)/1.45 var(--feitio-font-ui); color: var(--feitio-color-text-soft); }
.try-screen { color: var(--feitio-color-text); background: var(--feitio-color-surface); border: var(--feitio-border-width) solid var(--feitio-color-text); border-radius: var(--feitio-radius); overflow: hidden; font-family: var(--feitio-font-ui); }
.try-bar { display: flex; align-items: center; justify-content: space-between; gap: var(--feitio-space-3); padding: var(--feitio-space-3) var(--feitio-space-4); border-block-end: var(--feitio-border-width) solid var(--feitio-color-text); }
.try-bar strong { font: var(--feitio-font-weight-bold) var(--feitio-font-size-h3) var(--feitio-font-ui); }
.try-body { display: grid; gap: var(--feitio-space-4); padding: var(--feitio-space-4); }
.try-body .feitio-notice { margin: 0; }
.try-list { margin: 0; padding: 0; list-style: none; background: var(--feitio-color-surface-top); border: var(--feitio-border-width) solid var(--feitio-color-text); border-radius: var(--feitio-radius); }
.try-list li.try-slide { overflow: hidden; animation: try-slide var(--feitio-duration-change) var(--feitio-easing-change); }
@keyframes try-slide { from { max-block-size: 0; padding-block: 0; opacity: 0; translate: 0 -0.5rem; } to { max-block-size: 5rem; opacity: 1; translate: 0 0; } }
.try-list li { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--feitio-space-2); padding: var(--feitio-cell-padding-block, 0.75rem) var(--feitio-cell-padding-inline, 1rem); }
.try-list li + li { border-block-start: var(--feitio-border-width) solid var(--feitio-color-line); }
.try-list .when { font-size: var(--feitio-font-size-small); color: var(--feitio-color-text-soft); }
[data-theme="horta"] {
    --feitio-color-surface: oklch(96% 0.02 125); --feitio-color-surface-raised: oklch(92% 0.03 125); --feitio-color-surface-top: oklch(98.5% 0.01 120);
    --feitio-color-text: oklch(26% 0.03 150); --feitio-color-text-soft: oklch(45% 0.035 150);
    --feitio-color-accent: oklch(48% 0.12 150); --feitio-color-accent-strong: oklch(44% 0.12 150); --feitio-color-on-accent: oklch(98% 0.01 120);
    --feitio-color-line: oklch(26% 0.03 150 / 0.15); --feitio-color-shadow: oklch(26% 0.03 150 / 0.9);
    --feitio-color-ok: oklch(45% 0.09 140); --feitio-color-ok-surface: oklch(91% 0.04 135); --feitio-color-warn: oklch(50% 0.1 85); --feitio-color-warn-surface: oklch(92% 0.06 90); --feitio-color-error: oklch(45% 0.15 15); --feitio-color-error-surface: oklch(91% 0.04 15);
  }
[data-theme="horta"][data-mode="dark"] {
    --feitio-color-surface: oklch(22% 0.02 150); --feitio-color-surface-raised: oklch(27% 0.025 150); --feitio-color-surface-top: oklch(31% 0.028 150);
    --feitio-color-text: oklch(93% 0.02 120); --feitio-color-text-soft: oklch(76% 0.03 125);
    --feitio-color-accent: oklch(48% 0.12 150); --feitio-color-accent-strong: oklch(78% 0.12 145); --feitio-color-on-accent: oklch(98% 0.01 120);
    --feitio-color-line: oklch(93% 0.02 120 / 0.15); --feitio-color-shadow: oklch(12% 0.01 150 / 0.95);
    --feitio-color-ok: oklch(78% 0.1 140); --feitio-color-ok-surface: oklch(30% 0.04 140); --feitio-color-warn: oklch(83% 0.11 88); --feitio-color-warn-surface: oklch(32% 0.05 85); --feitio-color-error: oklch(76% 0.12 15); --feitio-color-error-surface: oklch(31% 0.06 15);
  }
.doors { display: grid; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); gap: var(--feitio-space-4); }
.doors .feitio-link-card > span { font: var(--feitio-font-size-small)/1.45 var(--feitio-font-ui); color: var(--feitio-color-text-soft); }

script:
for (const p of document.querySelectorAll('.feitio-time-field .period')) p.addEventListener('click', () => { p.textContent = p.textContent === 'AM' ? 'PM' : 'AM'; });
for (const s of document.querySelectorAll('.feitio-switch input')) s.addEventListener('change', () => {
  const st = s.closest('.feitio-switch').querySelector('.state');
  st.innerHTML = s.checked ? '<span lang="pt-BR">Ligado</span><span lang="en">On</span>' : '<span lang="pt-BR">Desligado</span><span lang="en">Off</span>';
});
for (const b of document.querySelectorAll('[data-seg-demo] button')) b.addEventListener('click', () => {
  for (const o of b.parentElement.querySelectorAll('button')) o.setAttribute('aria-pressed', String(o === b));
});
for (const b of document.querySelectorAll('[data-cycle-demo]')) b.addEventListener('click', () => {
  const f = document.getElementById('tf-demo'); f.dataset.hourCycle = b.dataset.cycleDemo;
  for (const o of document.querySelectorAll('[data-cycle-demo]')) o.setAttribute('aria-pressed', String(o === b));
});
  // AppShell: no mobile, o cabeçalho some ao rolar para baixo e volta ao rolar para cima.
  for (const header of document.querySelectorAll('[data-hide-on-scroll]')) {
    const frame = header.closest('.feitio-app-frame');
    const menu = header.querySelector('.menu');
    const own = frame && getComputedStyle(frame).overflowY !== 'visible';
    const target = own ? frame : window;
    const pos = () => (own ? frame.scrollTop : scrollY);
    let last = pos();
    target.addEventListener('scroll', () => {
      const y = pos();
      const mobile = menu && getComputedStyle(menu).display !== 'none';
      if (!mobile || y < header.offsetHeight) delete header.dataset.hidden;
      else if (y > last + 4) header.dataset.hidden = '';
      else if (y < last - 4) delete header.dataset.hidden;
      last = y;
    }, { passive: true });
    header.addEventListener('focusin', () => { delete header.dataset.hidden; });
  }


for (const b of document.querySelectorAll('[data-open-dialog]')) b.addEventListener('click', () => {
  const d = document.getElementById(b.dataset.openDialog); d?.showModal();
  d?.querySelector('[data-type-to-confirm] input')?.focus();
});
for (const form of document.querySelectorAll('[data-type-to-confirm]')) {
  const input = form.querySelector('input'), danger = form.querySelector('[data-variant="danger"]');
  input.addEventListener('input', () => { danger.disabled = input.value.trim().toUpperCase() !== form.dataset.typeToConfirm; });
  form.closest('dialog').addEventListener('close', () => { input.value = ''; danger.disabled = true; });
}

// Experimente: cada escolha põe um atributo na tela de exemplo; "Salvar" coloca um aviso como papel.
const tryScreen = document.getElementById('try-screen');
for (const b of document.querySelectorAll('[data-try]')) b.addEventListener('click', () => {
  for (const o of b.parentElement.querySelectorAll('button')) o.setAttribute('aria-pressed', String(o === b));
  const v = b.dataset.value;
  if (v) tryScreen.setAttribute(b.dataset.try, v); else tryScreen.removeAttribute(b.dataset.try);
});
// O papel colocado: a peça nova chega pela animação feitio-place; em "Direto", aparece sem animação.
const place = (el) => { el.classList.remove('feitio-place'); void el.offsetWidth; el.classList.add('feitio-place'); };
document.getElementById('try-save')?.addEventListener('click', () => {
  const n = document.getElementById('try-notice'), list = document.getElementById('try-list');
  const name = document.getElementById('try-name').value.trim() || 'Lembrete';
  const li = document.createElement('li');
  li.innerHTML = '<span class="feitio-stack" data-gap="1"><span class="feitio-link"></span><span class="when"><span lang="pt-BR">Amanhã, 9h</span><span lang="en">Tomorrow, 9 am</span></span></span><span class="feitio-tag" data-status="ok"><svg class="feitio-icon" aria-hidden="true"><use href="../../feitio/icons/sprite.svg#feitio-check"/></svg><span lang="pt-BR">Novo</span><span lang="en">New</span></span>';
  li.querySelector('.feitio-link').textContent = name;
  list.prepend(li);
  li.classList.add('try-slide'); window.feitioNotice ? feitioNotice.show(n) : place(n);
});
if (matchMedia('(prefers-reduced-motion: reduce)').matches) document.getElementById('try-calm').hidden = false;
